const PERIOD = 100; // number of points in each line and infinite loop size
const NUM = 1000; // number of flow lines
var particles = [NUM]; 
var noiseXYScale=.01;
var noiseStrength=2;

function setup() {
  createCanvas(650,650);
  background(0)  
  for (let i=0; i<NUM; i++) { 
    particles[i]= new Particle(random(width),random(height), i);
  }
}

function draw() {
  background(0,10); // transparent black (to create ghosting and fade old points)
  for (let i=0; i<particles.length; i++) { // draw point for each particle
    var particleIndex = round(i + (frameCount-1))%PERIOD; //offset within each line by the particle number
    particles[i].draw(particleIndex);
  }  
}

class Particle{
  constructor(x0,y0){
    this.x = [];
    this.y = [];
    this.x[0] = x0; //initialize flow line coordinate
    this.y[0] = y0;    
    for (let i=0; i<PERIOD; i++){
      let angle= TWO_PI*noiseStrength*noise(this.x[i]*noiseXYScale, this.y[i]*noiseXYScale,0); // perlin noise
      this.x[i+1] = this.x[i] + cos(angle); // move the points based on noise magnitude
      this.y[i+1] = this.y[i] + sin(angle);
    }
  }
  draw(i){
    var colorStart = color(50,255,50,255); //light green
    var colorEnd = color(50,50,255,255); //light blue
    noStroke();
    fill(lerpColor(colorStart,colorEnd,i/PERIOD));
    ellipse(this.x[i], this.y[i], 2);
  }
}
